172	/**
173	 * Build the idempotent reconcile script for a guest.
174	 *
175	 * Model: a dedicated chain (NXEON_FW) is created once and INPUT is made to jump
176	 * to it exactly once, at the top. On every sync the chain is FLUSHED and rebuilt
177	 * from scratch, so re-running with the same rule set yields the identical kernel
178	 * state (idempotent) and a partial previous run cannot accumulate stale rules.
179	 * Only OUR chain is ever flushed — the customer's own INPUT rules are untouched.
180	 *
181	 * Baseline (always, before any customer rule):
182	 *   - accept loopback
183	 *   - accept ESTABLISHED,RELATED (so existing/return traffic never breaks)
184	 *   - accept tcp/22  ← ANTI-LOCKOUT: SSH stays reachable no matter what the
185	 *     customer configures; a DENY on 22 can therefore never strand them.
186	 *
187	 * Customer rules follow in `position` order; iptables is first-match-wins, so
188	 * that order is the precedence the UI lets them control.
189	 *
190	 * Trailing default: a final DROP is appended ONLY when the customer has at least
191	 * one ALLOW rule (i.e. they have opted into whitelist / security-group
192	 * semantics). With only DENY rules, or none, the chain RETURNs and the packet
193	 * continues through the guest's own INPUT rules — so enabling the feature can
194	 * never silently black-hole a service the customer was already running.
195	 *
196	 * `rules` MUST be pre-validated (worker re-runs `validateRule` on each row).
197	 */
198	export function buildReconcileScript(rules: ValidatedRule[]): string {
199	  const lines: string[] = [];
200	  lines.push("set -o pipefail");
201	  lines.push("IPT=iptables");
202	  lines.push(`CHAIN=${FW_CHAIN}`);
203	  // Create the chain if missing (ignore "exists"), and jump INPUT → CHAIN once,
204	  // inserted at the top so our decisions run before the guest's own rules.
205	  lines.push('"$IPT" -N "$CHAIN" 2>/dev/null || true');
206	  lines.push('"$IPT" -C INPUT -j "$CHAIN" 2>/dev/null || "$IPT" -I INPUT 1 -j "$CHAIN"');
207	  // Rebuild our chain from scratch — the only flush, and only of our chain.
208	  lines.push('"$IPT" -F "$CHAIN"');
209	  lines.push('"$IPT" -A "$CHAIN" -i lo -j ACCEPT');
210	  lines.push('"$IPT" -A "$CHAIN" -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT');
211	  for (const p of FW_KEEP_OPEN_TCP_PORTS) {
212	    lines.push(`"$IPT" -A "$CHAIN" -p tcp --dport ${p} -j ACCEPT`);
213	  }
214	  for (const rule of rules) {
215	    lines.push(['"$IPT"', "-A", '"$CHAIN"', ...ruleToArgs(rule)].join(" "));
216	  }
217	  if (hasAnyAllow(rules)) {
218	    lines.push('"$IPT" -A "$CHAIN" -j DROP');
219	  }
220	  return lines.join("\n");
221	}
