223	/**
224	 * Human port/range label for one firewall rule. Lives in this PLAIN module (not the
225	 * "use client" NetworkingControls) so the server-rendered rules table can call it
226	 * directly — calling it from a client module crashed the page for any server that
227	 * actually had a rule to render.
228	 */
229	export function firewallPortLabel(rule: {
230	  protocol: string;
231	  portFrom: number | null;
232	  portTo: number | null;
233	}): string {
234	  if (rule.protocol === "ICMP" || rule.protocol === "ALL") return "—";
235	  if (rule.portFrom == null && rule.portTo == null) return "all";
236	  if (rule.portFrom === rule.portTo) return String(rule.portFrom);
237	  return `${rule.portFrom}–${rule.portTo}`;
238	}
