import { headers } from "next/headers";
import { db } from "./db";
import { ipInCidr } from "./firewall-rules";

/**
 * Per-employee IP allow-list gate for /staff, structurally parallel to
 * app/admin/layout.tsx's adminIpBlocked but scoped to one user's own
 * StaffIpAllow rows instead of a single global setting.
 *
 * Zero rows for this user = no restriction (fail OPEN) — a brand-new
 * employee isn't locked out before an admin gets around to configuring their
 * IPs. The moment even one row exists for THIS specific user, only a request
 * from an IP inside one of their allowed ranges is accepted (fail CLOSED);
 * every other employee with no rows of their own is completely unaffected,
 * since this only ever reads rows for the passed-in userId.
 *
 * Returns true when access should be REFUSED.
 */
export async function staffIpBlocked(userId: string): Promise<boolean> {
  const rows = await db.staffIpAllow.findMany({ where: { userId }, select: { cidr: true } });
  if (rows.length === 0) return false;

  const hdrs = await headers();
  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
  // client-supplied leftmost entry. Same anti-spoofing trust model as
  // app/admin/layout.tsx's adminIpBlocked.
  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
  if (!ip) {
    console.warn("[staff-ip] could not determine requester IP; failing open for user", userId);
    return false;
  }

  return !rows.some((r) => ipInCidr(ip, r.cidr));
}

import { redirect, notFound } from "next/navigation";
import { headers } from "next/headers";
import { realUser, impersonating } from "@/lib/auth";
import { GRANTABLE_AREAS, listGrantedAreas } from "@/lib/staff-grants";
import { staffIpBlocked } from "@/lib/staff-ip";
import { db } from "@/lib/db";
import { getSettingBool } from "@/lib/settings";
import { Shell, type NavSection } from "@/components/portal/Shell";

/**
 * Host gate: the employee portal is only reachable from the dedicated staff
 * hostname(s) in NXEON_STAFF_HOSTS (comma-separated) — same shape as
 * app/admin/layout.tsx's adminHostBlocked, deliberately kept a separate env
 * var so the two portals can live on different hosts independently. On any
 * other host, /staff 404s as if it doesn't exist. Empty/unset = no host
 * restriction (dev fallback).
 */
async function staffHostBlocked(): Promise<boolean> {
  const allow = (process.env.NXEON_STAFF_HOSTS ?? "")
    .split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
  if (allow.length === 0) return false;
  const host = ((await headers()).get("host") ?? "").toLowerCase().split(":")[0];
  return !allow.includes(host);
}

/** Leading nav icon (key into components/portal/Shell.tsx's `icons` map) per grantable area. */
const AREA_ICONS: Record<string, string> = {
  supportTickets: "lifebuoy",
  liveChat: "chat",
  redditTemplates: "content",
  companyInbox: "mail",
  companyMailboxes: "db",
  clientsBasic: "users",
  tasks: "queue",
};

export default async function StaffLayout({ children }: { children: React.ReactNode }) {
  // Wrong host (e.g. the public site or the admin host) → 404, so /staff isn't
  // reachable there.
  if (await staffHostBlocked()) notFound();

  const user = await realUser();
  if (!user) redirect("/login");
  // EMPLOYEE is this portal's real audience. ADMIN is let in too, deliberately:
  // it lets the owner log in and see exactly what a given employee's grants
  // produce before handing them out. Every other role (SUPPORT/BILLING/CUSTOMER)
  // keeps going exactly where it already does — this portal has nothing for them.
  if (user.role !== "EMPLOYEE" && user.role !== "ADMIN") redirect("/dashboard");
  const imp = await impersonating();
  if (imp) redirect("/dashboard"); // exit impersonation before using staff tools

  // Per-employee IP allow-list: refuses access from an IP that isn't explicitly
  // allowed for THIS user (see lib/staff-ip.ts for the fail-open/fail-closed
  // rule). An ADMIN previewing the portal has no StaffIpAllow rows, so this is a
  // no-op for them.
  if (await staffIpBlocked(user.id)) {
    return (
      <main
        style={{
          minHeight: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "0.75rem",
          padding: "2rem",
          textAlign: "center",
        }}
      >
        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
          The staff portal isn&apos;t available from your current network.
        </p>
      </main>
    );
  }

  // Staff 2FA enforcement: identical setting/redirect to app/admin/layout.tsx,
  // so turning it on protects both portals at once.
  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
    redirect("/dashboard/settings?require2fa=1");
  }

  // ADMIN previewing the portal has no StaffGrant rows and shouldn't need any —
  // show every grantable area so the owner sees exactly what full access looks
  // like before handing any of it to an employee. An EMPLOYEE only ever sees
  // what they've actually been granted.
  const grantedAreas = user.role === "ADMIN" ? GRANTABLE_AREAS.map((a) => a.area) : await listGrantedAreas(user.id);

  const items = GRANTABLE_AREAS.filter((a) => grantedAreas.includes(a.area)).map((a) => ({
    label: a.label,
    href: a.href,
    icon: AREA_ICONS[a.area],
  }));
  // No section label: unlike the admin portal's many labelled groups, the
  // employee portal is a single flat tool list sized to whatever that person
  // was actually granted — often just one or two items.
  const nav: NavSection[] = items.length > 0 ? [{ key: "staff", items }] : [];

  const notifications = await db.notification.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: 15,
  });

  return (
    <Shell
      nav={nav}
      tag="staff"
      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
      notifications={notifications.map((n) => ({
        id: n.id,
        title: n.title,
        body: n.body,
        href: n.href,
        readAt: n.readAt ? n.readAt.toISOString() : null,
        createdAt: n.createdAt.toISOString(),
      }))}
    >
      {children}
    </Shell>
  );
}

